import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_ids = None
        best_value = None

        if mandatory & blocked:
            return {"error": "impossible"}
        options = [job for job in jobs if job["id"] not in blocked]
        for subset in combinations(options, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = []
            for job in subset:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            feasible = True
            for _, change in sorted(events):
                active += change
                if active > capacity:
                    feasible = False
                    break
            if not feasible:
                continue
            value = sum(job["value"] for job in subset)
            if (best is None or value > best_value or
                (value == best_value and
                 ((tie == "largest" and ids > best_ids) or
                  (tie == "smallest" and ids < best_ids)))):
                best, best_ids, best_value = subset, ids, value
        if best is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = []
    rows_by_version = {}

    for name in names:
        rows = {row["version"]: row for row in packages[name]}
        rows_by_version[name] = rows
        versions = [v for v in rows
                    if v not in blocked.get(name, []) and
                    (name not in pins or v == pins[name])]
        domains.append([-1] + sorted(versions))

    best_vector = None
    best_assignment = None
    roots = data["roots"]
    for values in product(*domains):
        assignment = dict(zip(names, values))
        valid = True
        for name, (low, high) in roots.items():
            version = assignment.get(name, -1)
            if version == -1 or not low <= version <= high:
                valid = False
                break
        if not valid:
            continue

        graph = {}
        reached = set()
        stack = list(roots)
        while stack and valid:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            version = assignment.get(name, -1)
            if version == -1 or version not in rows_by_version.get(name, {}):
                valid = False
                break
            deps = []
            row = rows_by_version[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = assignment.get(target, -1)
                if target_version == -1 or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                deps.append(target)
                stack.append(target)
            graph[name] = deps
        if not valid:
            continue
        if any(value != -1 for value in values if False):
            pass
        if {name for name, version in assignment.items() if version != -1} != reached:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            state[name] = 2
            return True

        if any(not visit(name) for name in reached):
            continue
        vector = tuple(assignment[name] for name in names)
        if best_vector is None or vector < best_vector:
            best_vector, best_assignment = vector, assignment

    if best_assignment is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: version for name, version in best_assignment.items()
                          if version != -1}}


def _routes(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    def mark(node):
        result = 0
        for i, target in enumerate(required):
            if node == target:
                result |= 1 << i
        return result

    start = data["source"]
    initial = (start, mark(start), data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], start, initial[1], initial[2])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                choices.append((max(1, edge["duration"] - edge.get("discount", 0)),
                                coupons - 1))
            for duration, remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | mark(next_node)
                next_state = (next_node, next_mask, remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
    return {"arrival": None}


